//! `generated` (D2): generated files as data. A rule's scope names the
//! outputs, its `values` the sources that produce them. deno generates
//! `gen.rs` + `gen.js` from `runtime/features/data.rs` and 11 CI workflows
//! from `.ts` generators. harna does not run generators (no code execution
//! is a standing decision); it uses the declaration two ways:
//!
//! - outputs are exempt from size budgets (granularity, born-size) — a
//!   generated 7,000-line workflow is not an accretion problem;
//! - an output changed in the working tree while none of its sources did
//!   reads as a hand edit (Info) — regenerate instead.

use std::path::Path;

use super::{bound, finding, Violation};
use crate::schema::model::rules::Rules;
use crate::schema::model::scope::path_within;

/// Scopes declared generated by live rules.
pub fn outputs(rules: &Rules, env: Option<&str>) -> Vec<String> {
    bound(rules, env, "generated")
        .into_iter()
        .flat_map(|r| r.scope.iter().cloned())
        .collect()
}

pub fn is_generated(outputs: &[String], path: &str) -> bool {
    outputs.iter().any(|o| path_within(path, o))
}

pub fn check(root: &Path, rules: &Rules, env: Option<&str>, out: &mut Vec<Violation>) {
    let rules_here = bound(rules, env, "generated");
    if rules_here.is_empty() {
        return;
    }
    let Ok(changed) = crate::enforcement::validate::git::changed_files(root) else {
        return; // no git: nothing to compare
    };
    for rule in rules_here {
        let sources_moved = changed
            .iter()
            .any(|c| rule.values.iter().any(|s| path_within(c, s)));
        if sources_moved {
            continue;
        }
        for c in changed
            .iter()
            .filter(|c| rule.scope.iter().any(|s| path_within(c, s)))
        {
            out.push(finding(
                "generated",
                c,
                0,
                format!(
                    "generated output changed while its sources ({}) did not — a hand edit? (rule `{}`)",
                    rule.values.join(", "),
                    rule.id
                ),
                "edit the source and regenerate; hand edits are lost on the next run".into(),
            ));
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_scopes_are_matched_by_path() {
        let outs = vec![
            ".github/workflows/ci.generated.yml".to_string(),
            "runtime/features/gen".to_string(),
        ];
        assert!(is_generated(&outs, ".github/workflows/ci.generated.yml"));
        assert!(is_generated(&outs, "runtime/features/gen/gen.rs"));
        assert!(!is_generated(&outs, "runtime/features/data.rs"));
    }
}
